DO $$ BEGIN ASSERT NOT EXISTS (SELECT 1 FROM (VALUES ('{"isPublic":true,"_discoveryOwned":{"title":"Source","isPublic":true}}', true), ('{"isPublic":true,"_discoveryOwned":{}}', true), ('{"isPublic":false,"_discoveryOwned":{}}', false), ('{"isPublic":true,"_discoveryOwned":null}', false), ('{"isPublic":true,"_discoveryOwned":false}', false), ('{"isPublic":true,"_discoveryOwned":[]}', false), ('{"isPublic":true,"_discoveryOwned":{},"unexpected":1}', false), ('{"isPublic":true,"_discoveryOwned":{},"_discoveryOwned":{}}', false), ('{"isPublic":true,"budgetCents":1.5,"_discoveryOwned":{}}', false), ('{"isPublic":true,"budgetCents":9223372036854775807.0,"_discoveryOwned":{}}', true)) AS test(metadata,expected) WHERE (CASE WHEN metadata IS NULL OR btrim(metadata)='' THEN TRUE WHEN NOT pg_input_is_valid(metadata,'jsonb') THEN FALSE ELSE jsonb_typeof((metadata)::jsonb)='object' AND (SELECT count(*) FROM json_each((metadata)::json))=(SELECT count(DISTINCT metadata_field.key) FROM json_each((metadata)::json) AS metadata_field) AND NOT EXISTS (SELECT 1 FROM jsonb_object_keys((metadata)::jsonb) AS metadata_key WHERE metadata_key NOT IN ('ticketUrl','imageUrl','isPublic','currency','budgetCents','_discoveryOwned')) AND (jsonb_typeof((metadata)::jsonb->'_discoveryOwned') IS NULL OR jsonb_typeof((metadata)::jsonb->'_discoveryOwned')='object') AND (jsonb_typeof((metadata)::jsonb->'ticketUrl') IS NULL OR jsonb_typeof((metadata)::jsonb->'ticketUrl') IN ('null','string')) AND (jsonb_typeof((metadata)::jsonb->'imageUrl') IS NULL OR jsonb_typeof((metadata)::jsonb->'imageUrl') IN ('null','string')) AND (jsonb_typeof((metadata)::jsonb->'currency') IS NULL OR jsonb_typeof((metadata)::jsonb->'currency') IN ('null','string')) AND (jsonb_typeof((metadata)::jsonb->'budgetCents') IS NULL OR jsonb_typeof((metadata)::jsonb->'budgetCents')='null' OR CASE WHEN jsonb_typeof((metadata)::jsonb->'budgetCents')='number' THEN ((metadata)::jsonb->>'budgetCents')::numeric=trunc(((metadata)::jsonb->>'budgetCents')::numeric) AND ((metadata)::jsonb->>'budgetCents')::numeric BETWEEN -9223372036854775808 AND 9223372036854775807 ELSE FALSE END) AND (jsonb_typeof((metadata)::jsonb->'isPublic') IS NULL OR jsonb_typeof((metadata)::jsonb->'isPublic')='null' OR (metadata)::jsonb->'isPublic'='true'::jsonb) END) IS DISTINCT FROM expected), 'Ownership metadata visibility mismatch'; END $$; SELECT 'PASS: 10 actual source-derived PostgreSQL predicate cases';
